from pwn import *
import binascii
import time

context.log_level = 'error'

def get_cookie(length):
    try:
        # Connect to server
        r = remote('crypto.chal.csaw.io', 8000)

        # Send username
        username = 'A' * length
        r.sendlineafter(b'Enter username: ', username.encode())

        # Get response
        response = r.recvline_contains(b'cookie=').decode()
        cookie = response.split('cookie=')[1].strip()

        return cookie
    except Exception as e:
        log.error(f"Error on length {length}: {str(e)}")
        return None
    finally:
        try:
            r.close()
        except:
            pass

def analyze_cookie(cookie):
    if not cookie:
        return None

    try:
        # Convert cookie to bytes
        cookie_bytes = binascii.unhexlify(cookie)

        # Create formatted hex output
        hex_dump = binascii.hexlify(cookie_bytes).decode()
        hex_formatted = ' '.join(hex_dump[i:i+2] for i in range(0, len(hex_dump), 2))

        return {
            'length': len(cookie_bytes),
            'hex': hex_formatted
        }
    except Exception as e:
        log.error(f"Error analyzing cookie: {str(e)}")
        return None

def main():
    print("Analyzing cookie patterns for different username lengths...")
    print("\nUsername length | Cookie length | Cookie hex pattern")
    print("-" * 70)

    for length in range(1, 17):
        cookie = get_cookie(length)
        if cookie:
            result = analyze_cookie(cookie)
            if result:
                print(f"{length:14d} | {result['length']:12d} | {result['hex']}")
        time.sleep(0.5)  # Small delay between attempts

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
from pwn import *
import codecs
import binascii
import string

context.log_level = 'debug'

def try_xor(data, key):
    return bytes(b ^ key for b in data)

def try_rot13_hex(hex_str):
    try:
        text = codecs.decode(hex_str, 'hex')
        rot13 = codecs.encode(text.decode(), 'rot13')
        return rot13
    except:
        return None

def try_bit_shifts(data):
    results = []
    # Left shifts
    for i in range(1, 8):
        shifted = bytes(((b << i) & 0xFF) for b in data)
        results.append(shifted)
    # Right shifts
    for i in range(1, 8):
        shifted = bytes(((b >> i) & 0xFF) for b in data)
        results.append(shifted)
    return results

def reverse_hex(hex_str):
    byte_pairs = [hex_str[i:i+2] for i in range(0, len(hex_str), 2)]
    reversed_pairs = byte_pairs[::-1]
    return ''.join(reversed_pairs)

def is_printable(s):
    return all(c in string.printable.encode() for c in s)

def test_solution(r, payload):
    try:
        r.sendline(payload)
        response = r.recvline(timeout=2)
        print(f"Response for {payload}: {response}")
        return response
    except:
        return None

# Connect to the server
while True:
    try:
        r = remote('crypto.chal.csaw.io', 8000, timeout=5)
        print("Connected to server")
        break
    except:
        print("Connection failed, retrying...")
        time.sleep(1)

# Send test username and get cookie
test_username = b'test'
r.sendline(test_username)
try:
    response = r.recvline(timeout=2).decode().strip()
    print(f"Server response: {response}")

    if 'Cookie:' in response:
        cookie = response.split('Cookie: ')[1]
        print(f"Retrieved cookie: {cookie}")
        cookie_bytes = bytes.fromhex(cookie)

        # 1. XOR with common values
        for key in range(256):
            xor_result = try_xor(cookie_bytes, key)
            if is_printable(xor_result):
                print(f"[+] XOR with 0x{key:02x}: {xor_result}")
                test_solution(r, xor_result)

        # 2. Try ROT13
        rot13_result = try_rot13_hex(cookie)
        if rot13_result:
            print(f"[+] ROT13: {rot13_result}")
            test_solution(r, rot13_result.encode())

        # 3. Reverse the bytes
        reversed_hex = reverse_hex(cookie)
        reversed_bytes = bytes.fromhex(reversed_hex)
        print(f"[+] Reversed: {reversed_bytes}")
        test_solution(r, reversed_bytes)

        # 4. Bit shifts
        shifted_results = try_bit_shifts(cookie_bytes)
        for i, result in enumerate(shifted_results):
            if is_printable(result):
                print(f"[+] Shift {i}: {result}")
                test_solution(r, result)

except EOFError:
    print("Connection closed by remote host")
finally:
    r.close()
